import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
const data={
 jala:{title:'Wau Jala Budi',short:'Jala Budi',number:'01',summary:'Lengkungan anggun berinspirasikan daun budi, dengan ekor tajam yang unik.',info:{kepala:'Dilengkapi dengan busur atau dengung yang menghasilkan bunyi berdengung sederhana garau apabila diterbangkan.',sayap:'Mempunyai rentangan sayap yang melengkung anggun, diinspirasikan daripada bentuk daun pokok budi (daun beringin).',corak:'Menggunakan motif ukiran tradisional flora dan tumbuh-tumbuhan tempatan.',ekor:'Bahagian pinggul/ekor berbentuk tajam dan melengkung yang unik, menyerupai susunan daun.'}},
 kucing:{title:'Wau Kucing',short:'Kucing',number:'02',summary:'Bentuk yang tersendiri, dengan sayap seimbang dan ekor membulat lebar.',info:{kepala:'Bahagian mukanya direka bentuk menyerupai kepala kucing yang mempunyai telinga menonjol.',sayap:'Sayap melengkung lebar yang seimbang dengan bentuk badannya.',corak:'Dihiasi dengan motif pilihan seperti awan larat atau kelarai menggunakan teknik sobek tradisional.',ekor:'Bahagian ekor dan bawahnya membulat lebar menyerupai bentuk badan seekor kucing yang sedang duduk jika dilihat dari belakang.'}},
 seri:{title:'Wau Seri Bulan',short:'Seri Bulan',number:'03',summary:'Perincian sobek yang rumit, sayap simetri dan ekor bulan sabit yang elegan.',info:{kepala:'Bahagian kepala dihiasi elemen struktur yang kemas serta rumbai berwarna-warni.',sayap:'Sayap simetri yang lebar dan tegap untuk kestabilan di udara.',corak:'Mempunyai reka corak ukiran (sobek) yang sangat teliti, padat, dan rumit berasaskan motif flora tempatan.',ekor:'Ekor berbentuk bulan sabit membulat yang simetris dan elegan.'}},
 bulan:{title:'Wau Bulan',short:'Bulan',number:'04',summary:'Sayap bujur dan ekor bulan sabit — identiti yang indah dalam seni wau.',info:{kepala:'Berbentuk segi tiga dan dilengkapi dengan busur di atasnya serta rumbai penjuru bagi menambah seri.',sayap:'Sayap berbentuk elips atau bujur yang melebar simetris ke kiri dan kanan.',corak:'Permukaan badan dan sayap dipenuhi corak awan larat serta bunga-bungaan (seperti pucuk rebung dan bunga pepohon menjalar) menggunakan teknik sobek kertas berwarna-warni.',ekor:'Ekor berbentuk bulan sabit tajam ke atas yang melambangkan keindahan dan kesempurnaan serta menjadi identiti utama wau ini.'}}
};
const names={kepala:'Kepala',sayap:'Sayap',corak:'Corak',ekor:'Ekor'},keys=Object.keys(names),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let current='kucing',selected=null,exploded=false,labelled=true,rotating=false,loadVersion=0,ready=false,meshes=[],modelTexture,animation=null;
const empty=$('#detail').innerHTML;
const stage=$('#stage'),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,1,.01,50);
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});}catch(e){$('#loading').innerHTML='<div class="error-message">Browser ini tidak dapat memaparkan 3D. Sila buka dengan Chrome atau Edge yang menyokong WebGL.</div>';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;stage.appendChild(renderer.domElement);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.075;controls.enablePan=false;controls.minDistance=.65;controls.maxDistance=4.4;controls.autoRotateSpeed=.65;
scene.add(new THREE.HemisphereLight(0xffffff,0xc0c8b5,2.5));const light=new THREE.DirectionalLight(0xfff3de,2.3);light.position.set(-2,3,5);scene.add(light);const fill=new THREE.DirectionalLight(0xe8fff4,.8);fill.position.set(3,0,-3);scene.add(fill);
const root=new THREE.Group();root.position.y=-.49;scene.add(root);
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function fitDistance(){return 2.25*Math.max(1,.88/camera.aspect)}
function resize(){const {width,height}=stage.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();if(!ready)camera.position.set(.025,.015,fitDistance());}
new ResizeObserver(resize).observe(stage);resize();controls.target.set(0,0,0);controls.update();
function tweenCamera(target,dist){const start=camera.position.clone(),startTarget=controls.target.clone(),end=new THREE.Vector3(target[0],target[1],dist);animation={start,startTarget,end,endTarget:new THREE.Vector3(...target),time:performance.now(),duration:reduceMotion?0:750};}
function home(){selected=null;exploded=false;rotating=false;controls.autoRotate=false;$('#rotate').setAttribute('aria-pressed','false');$('#detail').innerHTML=empty;sync();tweenCamera([0,0,0],fitDistance());}
function sync(){$('#explode').setAttribute('aria-pressed',String(exploded));$('#explode span').textContent=exploded?'Cantumkan semula':'Pisahkan bahagian';$$('[data-part]').forEach(b=>b.classList.toggle('active',b.dataset.part===selected));}
function selectPart(key){if(!ready)return;selected=key;rotating=false;controls.autoRotate=false;$('#rotate').setAttribute('aria-pressed','false');const index=keys.indexOf(key),model=data[current];$('#detail').innerHTML=`<div class="detail-content"><div class="detail-top"><span class="eyebrow">BAHAGIAN ${String(index+1).padStart(2,'0')} / 04</span><button class="close" aria-label="Tutup maklumat">×</button></div><h3>${names[key]} Wau</h3><div class="detail-model">${model.title}</div><div class="detail-line"></div><p class="detail-description">${model.info[key]}</p><div class="detail-tag">${key==='corak'?'Paparan dekat motif pada permukaan model.':'Bahagian ini ditonjolkan pada model 3D. Seret untuk melihat dari sudut lain.'}</div><div class="detail-nav"><button id="prevPart" aria-label="Bahagian sebelumnya">←</button><span>${index+1} daripada 4 bahagian</span><button id="nextPart" aria-label="Bahagian seterusnya">→</button></div></div>`;$('.close').onclick=()=>{selected=null;$('#detail').innerHTML=empty;sync();tweenCamera([0,exploded?-.07:0,0],fitDistance()*(exploded?1.5:1))};$('#prevPart').onclick=()=>selectPart(keys[(index+3)%4]);$('#nextPart').onclick=()=>selectPart(keys[(index+1)%4]);
 if(key==='corak'){exploded=false;tweenCamera([0,.065,0],fitDistance()*.53);}else {tweenCamera([0,exploded?-.07:0,0],fitDistance()*(exploded?1.5:1));}sync();
 if(innerWidth<=800)$('#detail').scrollIntoView({behavior:reduceMotion?'instant':'smooth',block:'nearest'});
}
$$('[data-part]').forEach(b=>b.onclick=()=>selectPart(b.dataset.part));
async function loadModel(id){const version=++loadVersion;current=id;ready=false;selected=null;exploded=false;rotating=false;controls.autoRotate=false;$('#rotate').setAttribute('aria-pressed','false');$('#detail').innerHTML=empty;$('#loading').classList.remove('hidden');$('#loadText').textContent='Memuatkan model 3D';const model=data[id];$('#modelTitle').innerHTML=`Wau <br>${model.short}`;$('#modelSummary').textContent=model.summary;$('#modelNumber').textContent=`KOLEKSI ${model.number} / 04`;$$('[data-model]').forEach(b=>{b.classList.toggle('selected',b.dataset.model===id);b.setAttribute('aria-pressed',String(b.dataset.model===id))});sync();
 for(const m of meshes){root.remove(m);m.geometry.dispose();m.material.dispose()}meshes=[];modelTexture?.dispose();modelTexture=null;camera.position.set(.025,.015,fitDistance());controls.target.set(0,0,0);animation=null;controls.update();
 try{const meta=await fetch(`assets/${id}.json`).then(r=>{if(!r.ok)throw Error('meta');return r.json()});const [buffer,texture]=await Promise.all([fetch(`assets/${id}.bin`).then(r=>{if(!r.ok)throw Error('model');return r.arrayBuffer()}),new THREE.TextureLoader().loadAsync(`assets/${id}.jpg`)]);if(version!==loadVersion){texture.dispose();return;}texture.flipY=false;texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());modelTexture=texture;const positions=new THREE.BufferAttribute(new Float32Array(buffer,0,meta.count*3),3),normals=new THREE.BufferAttribute(new Float32Array(buffer,meta.normalOffset,meta.count*3),3),uv=new THREE.BufferAttribute(new Float32Array(buffer,meta.uvOffset,meta.count*2),2);
 for(const part of meta.parts){const g=new THREE.BufferGeometry();g.setAttribute('position',positions);g.setAttribute('normal',normals);g.setAttribute('uv',uv);g.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,part.offset,part.count),1));g.computeBoundingSphere();const mat=new THREE.MeshStandardMaterial({map:texture,roughness:.72,metalness:.04,side:THREE.DoubleSide});const m=new THREE.Mesh(g,mat);m.name=part.name;m.userData={key:part.key,direction:new THREE.Vector3(...part.direction)};root.add(m);meshes.push(m)}ready=true;$('#loading').classList.add('hidden');window.wauState=()=>({model:current,selected,exploded,ready,meshCount:meshes.length,triangles:meta.parts.reduce((s,p)=>s+p.count/3,0)});
 }catch(error){if(version!==loadVersion)return;$('#loading').innerHTML='<div class="error-message"><strong>Model belum dapat dimuatkan.</strong><p>Semak sambungan dan cuba sekali lagi.</p><button class="primary" id="retry">Cuba semula</button></div>';$('#retry').onclick=()=>{location.reload()};console.error(error)}
}
$$('[data-model]').forEach(b=>b.onclick=()=>loadModel(b.dataset.model));
$('#explode').onclick=()=>{if(!ready)return;exploded=!exploded;rotating=false;controls.autoRotate=false;$('#rotate').setAttribute('aria-pressed','false');if(selected==='corak'){selected=null;$('#detail').innerHTML=empty;}tweenCamera([0,exploded?-.07:0,0],fitDistance()*(exploded?1.5:1));sync()};
$('#labels').onclick=()=>{labelled=!labelled;$('#labels').setAttribute('aria-pressed',String(labelled));$('#hotspots').style.display=labelled?'':'none'};
$('#rotate').onclick=()=>{if(!ready)return;rotating=!rotating;controls.autoRotate=rotating;$('#rotate').setAttribute('aria-pressed',String(rotating))};$('#reset').onclick=home;
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.stage-wrap').requestFullscreen()}catch(e){console.warn(e)}};
document.addEventListener('fullscreenchange',()=>{const panel=$('#detail');if(document.fullscreenElement)$('.stage-wrap').appendChild(panel);else $('.explorer').appendChild(panel);resize()});
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;
renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,time:performance.now()};animation=null});renderer.domElement.addEventListener('wheel',()=>{animation=null},{passive:true});
renderer.domElement.addEventListener('pointerup',e=>{if(!ready||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6||performance.now()-down.time>600)return;const r=stage.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(meshes)[0];if(hit)selectPart(hit.object.userData.key)});
const anchors={kepala:[.03,.85,.05],sayap:[.29,.56,.08],corak:[-.19,.57,.09],ekor:[.14,.2,.08]},p3=new THREE.Vector3();let last=performance.now();
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;const blend=reduceMotion?1:1-Math.exp(-dt*8);
 for(const m of meshes){const desired=m.userData.direction.clone().multiplyScalar(exploded?1:0);if(selected===m.userData.key)desired.z+=.065;m.position.lerp(desired,blend);const emphasized=!selected||selected==='corak'||selected===m.userData.key;const tone=emphasized?1:.52;const color=m.material.color;const c=THREE.MathUtils.lerp(color.r,tone,blend);color.setRGB(c,c,c);}
 if(animation){const t=animation.duration?Math.min(1,(now-animation.time)/animation.duration):1;const ease=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;camera.position.lerpVectors(animation.start,animation.end,ease);controls.target.lerpVectors(animation.startTarget,animation.endTarget,ease);if(t===1)animation=null;}
 controls.update();root.updateMatrixWorld();for(const b of $$('#hotspots button')){const key=b.dataset.part;const coords=anchors[key];p3.set(...coords);p3.y-=.49;const m=meshes.find(x=>key==='corak'?x.name==='Sayap kiri':x.userData.key===key&&(key!=='sayap'||x.name==='Sayap kanan'));if(m)p3.add(m.position);p3.project(camera);const w=stage.clientWidth,h=stage.clientHeight;const x=(p3.x*.5+.5)*w,y=(-p3.y*.5+.5)*h;b.style.left=x+'px';b.style.top=y+'px';b.style.transform=x>w-95?'translate(-100%,-50%)':'translate(-5px,-50%)';b.style.flexDirection=x>w-95?'row-reverse':'row';b.style.visibility=ready&&p3.z<1&&x>8&&x<w-8&&y>55&&y<h-100?'visible':'hidden';}
 renderer.render(scene,camera);
}
requestAnimationFrame(frame);loadModel('kucing');
